    settingsTab: oneOf(["general", "virtual", "backup", "help"]),
    sort: oneOf(["saved", "name", "market", "profit", "wage", "margin", "own", "reference"]),
    direction: oneOf([1, -1]),
    materialSort: oneOf(["name", "inventoryCount", "manufacturing", "enhancement", "required", "shortage", "market"]),
    materialDirection: oneOf([1, -1]),
