    listingFilter: oneOf(["all", "mine", "behind", "unknown"]),
    shortagesOnly: value => typeof value === "boolean",
    presetHideOrdinary: value => typeof value === "boolean",
    presetLevels: value => Array.isArray(value) && value.length <= 21 && value.every(level => Number.isInteger(level) && level >= 0 && level <= 20) && new Set(value).size === value.length,
