          snapshot = data;
          snapshotAt = at;
          snapshotCached = false;
          try { storage?.setItem(cacheKey, JSON.stringify(data)); snapshotCacheError = ""; }
          catch (_error) { snapshotCacheError = "市场快照保存失败，本次快照仅在当前页面有效"; }
