      amount.type = "text"; amount.inputMode = "decimal";
      amount.setAttribute("aria-label", `${mode === "manufacturing" ? "制造" : "强化"}材料模拟单价：${label}`);
      amount.dataset.focusKey = `simulation-input:${key}:${mode}:${hrid}`;
      const note = node("small");
