        lower.title = previous == null ? "无可用更低档位" : `模拟${side === "a" ? "左一" : "右一"}：${number(previous)}`;
        higher.title = next == null ? "无可用更高档位" : `模拟${side === "a" ? "左一" : "右一"}：${number(next)}`;
        note.textContent = !latest ? "计算未就绪，请重新展开项目重试" : quote == null ? "无市场报价，请先读取该材料行情" : "";
